Here is the commit message:
mtd: intel-dg: Fix accessing regions before setting nregions

The regions array is counted by nregions, but it's set only after
accessing it:

[] UBSAN: array-index-out-of-bounds in drivers/mtd/devices/mtd_intel_dg.c:750:15
[] index 0 is out of range for type '<unknown> [*]'

Fix it by also fixing an undesired behavior: the loop silently ignores
ENOMEM and continues setting the other entries.

CC: Gustavo A. R. Silva <gustavoars@kernel.org>
CC: Raag Jadav <raag.jadav@intel.com>
Reported-by: Jani Partanen <jiipee@sotapeli.fi>
Closes: https://lore.kernel.org/all/caca6c67-4f1d-49f1-948f-e63b6b937b29@sotapeli.fi
Fixes: ceb5ab3cb646 ("mtd: add driver for intel graphics non-volatile memory device")
Signed-off-by: Lucas De Marchi <demarchi@kernel.org>
Signed-off-by: Alexander Usyskin <alexander.usyskin@intel.com>
Reviewed-by: Raag Jadav <raag.jadav@intel.com>
Signed-off-by: Miquel Raynal <miquel.raynal@bootlin.com>

Here is the root cause:
The driver sets the `nregions` field of the `nvm` structure after populating the `regions` array. Because `nregions` is used to define the array size (likely a flexible array member), accessing the array before `nregions` is assigned causes the compiler/language rules to treat it as a zero-length array, leading to an out-of-bounds access when writing `nvm->regions[0]`.

Here is the patch:

 static int intel_dg_mtd_probe(struct auxiliary_device *aux_dev,
 			      const struct auxiliary_device_id *aux_dev_id)
 {
 	struct intel_dg_nvm_dev *invm = auxiliary_dev_to_intel_dg_nvm_dev(aux_dev);
 	struct intel_dg_nvm *nvm;
 	struct device *device;
 	unsigned int nregions;
 	unsigned int i, n;
 	int ret;

 	device = &aux_dev->dev;

 	/* count available regions */
 	for (nregions = 0, i = 0; i < INTEL_DG_NVM_REGIONS; i++) {
 		if (invm->regions[i].name)
 			nregions++;
 	}

 	if (!nregions) {
 		dev_err(device, "no regions defined\n");
 		return -ENODEV;
 	}

 	nvm = kzalloc(struct_size(nvm, regions, nregions), GFP_KERNEL);
 	if (!nvm)
 		return -ENOMEM;

 	kref_init(&nvm->refcnt);
 	mutex_init(&nvm->lock);
+	nvm->nregions = nregions;

 	for (n = 0, i = 0; i < INTEL_DG_NVM_REGIONS; i++) {
 		if (!invm->regions[i].name)
 			continue;

 		char *name = kasprintf(GFP_KERNEL, "%s.%s",
 				       dev_name(&aux_dev->dev), invm->regions[i].name);
-		if (!name)
-			continue;
+		if (!name) {
+			ret = -ENOMEM;
+			goto err;
+		}
+
 		nvm->regions[n].name = name;
 		nvm->regions[n].id = i;
 		n++;
 	}
-	nvm->nregions = n; /* in case where kasprintf fail */

 	ret = devm_pm_runtime_enable(device);
 	if (ret < 0) {
 		dev_err(device, "rpm: enable failed %d\n", ret);
 		goto err_norpm;
 	}

 	pm_runtime_set_autosuspend_delay(device, INTEL_DG_NVM_RPM_TIMEOUT_MS);
 	pm_runtime_use_autosuspend(device);

 	ret = pm_runtime_resume_and_get(device);
 	if (ret < 0) {
 		dev_err(device, "rpm: get failed %d\n", ret);
 		goto err_norpm;
 	}

 	nvm->base = devm_ioremap_resource(device, &invm->bar);
 	if (IS_ERR(nvm->base)) {
 		ret = PTR_ERR(nvm->base);
 		goto err;
 	}

 	if (invm->non_posted_erase) {
 		nvm->base2 = devm_ioremap_resource(device, &invm->bar2);
 		if (IS_ERR(nvm->base2)) {
 			ret = PTR_ERR(nvm->base2);
 			goto err;
 		}
 	}

 	ret = intel_dg_nvm_init(nvm, device, invm->non_posted_erase);
 	if (ret < 0) {
 		dev_err(device, "cannot initialize nvm %d\n", ret);
 		goto err;
 	}

 	ret = intel_dg_nvm_init_mtd(nvm, device, ret, invm->writable_override);
 	if (ret) {
 		dev_err(device, "failed init mtd %d\n", ret);
 		goto err;
 	}

 	dev_set_drvdata(&aux_dev->dev, nvm);

 	pm_runtime_put(device);
 	return 0;

 err:
 	pm_runtime_put(device);
 err_norpm:
 	kref_put(&nvm->refcnt, intel_dg_nvm_release);
 	return ret;
 }



